fn fixture(name:&str)->serde_json::Value{serde_json::from_str(match name{"inputs"=>runtime_fixture_text("../../../../../../🧱️base/🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/🏛️inputs.json"),"snapshots"=>runtime_fixture_text("../../../../../../🧱️base/🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/📸️snapshots.json"),"malformed"=>runtime_fixture_text("../../../../../../🧱️base/🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/⚠️malformed.json"),_=>runtime_fixture_text("../../../../../../🧱️base/🚪️io/🪶️sqlite/📸️snapshot/🫴️receiving/🧪️tests/🧫️fixtures/🎟️grants.json")}).unwrap()}
fn grant(value:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(value.clone()).unwrap()}
fn scalar(value:&serde_json::Value)->SqliteValue{match value{serde_json::Value::Null=>SqliteValue::Null,serde_json::Value::String(v)=>SqliteValue::Text(v.clone()),serde_json::Value::Number(v)=>SqliteValue::Real(v.as_f64().unwrap()),_=>SqliteValue::Integer(value["integer"].as_str().unwrap().parse().unwrap())}}
fn input(index:usize)->SqliteDatabase{use semio_framework_os_kernel::sqlite_snapshot::SqliteTable;let all=fixture("inputs");SqliteDatabase{tables:all[index]["tables"].as_array().unwrap().iter().map(|table|SqliteTable{name:table["name"].as_str().unwrap().into(),sql:table["sql"].as_str().unwrap().into(),rows:table["rows"].as_array().unwrap().iter().map(|row|SqliteRow{rowid:row["rowid"].as_str().unwrap().parse().unwrap(),values:row["values"].as_array().unwrap().iter().map(scalar).collect()}).collect()}).collect()}}
fn tree(value:&serde_json::Value)->JsonValue{match value["kind"].as_str().unwrap(){"null"=>JsonValue::Null,"bool"=>JsonValue::Bool{value:value["value"].as_bool().unwrap()},"number"=>JsonValue::Number{lexeme:value["lexeme"].as_str().unwrap().into()},"string"=>JsonValue::String{value:value["value"].as_str().unwrap().into()},"array"=>JsonValue::Array{items:value["items"].as_array().unwrap().iter().map(tree).collect()},_=>JsonValue::Object{members:value["members"].as_array().unwrap().iter().map(|member|JsonMember{key:member["key"].as_str().unwrap().into(),value:tree(&member["value"])}).collect()}}}
fn snapshot(index:usize)->JsonSnapshot{let all=fixture("snapshots");JsonSnapshot{schema:all[index]["schema"].as_str().unwrap().into(),value:tree(&all[index]["value"])}}
fn close<T:semio_framework_value::retirement::RetireOwned>(original:T,policy:RetainedCloneGrant)->(usize,usize){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(original).ok().unwrap();let(mut born,mut freed)=(0,0);for _ in 0..4096{if owner.terminal_is_empty(){break}let(step,heap)=observe(||owner.step(policy).unwrap());assert!(step.progress().fits(policy));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(owner.terminal_is_empty());(born,freed)}
macro_rules! original{
 ($name:ident,$native:ident,$owner:ident,$recipient:path,$output:ty)=>{
  fn $name(policy:RetainedCloneGrant,callback:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool,operation:impl FnOnce(&mut SqliteSnapshotControl<'_>,&mut $owner<'_,'_>)->Result<$output,ValueError>)->(Result<$output,ValueError>,RetainedCloneProgress,usize,usize){
   let laws=fixture("grants");let denied=grant(&laws["denied"]);let closing=grant(&laws["close"]);let mut observer=|_|true;let mut recipient=<$recipient>::new();let mut native=$native::new(16777216,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut sql=SqliteSnapshotControl::new(callback,Default::default());let before=sql.allocation_remaining_bytes();let mut owner=$owner::new(&mut native,policy);let(result,heap)=observe(||operation(&mut sql,&mut owner));let receipt=owner.progress();assert!(receipt.fits(policy));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));if let Err(error)=&result{assert_eq!(error.retained_progress(),receipt)}drop(owner);assert_eq!(before-sql.allocation_remaining_bytes(),native.owned_bytes());let(mut born,mut freed)=(heap.requested_bytes,heap.released_bytes);let(zero,heap)=observe(||native.close_retirement_recipient(denied).unwrap());assert_eq!(zero.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for _ in 0..4096{if !native.has_retirement_owner(){break}let(step,heap)=observe(||native.close_retirement_recipient(closing).unwrap());assert!(step.progress().fits(closing));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(!native.has_retirement_owner());(result,receipt,born,freed)
  }
 };
}
