#[test]
fn json_original_receiving_all_six_tags_original_lexemes_duplicate_keys_and_backing(){let laws=fixture("grants");let paid=grant(&laws["body"]);let closing=grant(&laws["close"]);for index in 0..fixture("inputs").as_array().unwrap().len(){let original=input(index);let pointer=original.tables.as_ptr();let expected=snapshot(index);let(result,_,born,freed)=encode(paid,&mut |_|true,|sql,owner|JsonSnapshot::from_sqlite_database_receiving(&original,sql,owner));let restored=result.unwrap();assert_eq!(restored,expected);assert_eq!(pointer,original.tables.as_ptr());let(result,_,pborn,pfreed)=decode(paid,&mut |_|true,|sql,owner|restored.to_sqlite_database_receiving(sql,owner));let database=result.unwrap();let(roundtrip,_,rborn,rfreed)=encode(paid,&mut |_|true,|sql,owner|JsonSnapshot::from_sqlite_database_receiving(&database,sql,owner));let roundtrip=roundtrip.unwrap();assert_eq!(roundtrip,restored);let(a,b)=close(restored,closing);assert_eq!(born+a,freed+b);let(a,b)=close(database,closing);assert_eq!(pborn+a,pfreed+b);let(a,b)=close(roundtrip,closing);assert_eq!(rborn+a,rfreed+b);}}
#[test]
fn json_original_receiving_five_denied_axes_and_malformed_rows_retain_original(){let laws=fixture("grants");let paid=grant(&laws["body"]);let source=snapshot(0);let original=input(0);for axis in 0..5{let mut policy=paid;match axis{0=>policy.maximum_items=0,1=>policy.maximum_copy_bytes=0,2=>policy.maximum_capacity_bytes=0,3=>policy.maximum_release_bytes=0,_=>policy.maximum_depth=0}let(result,_,born,freed)=decode(policy,&mut |_|true,|sql,owner|source.to_sqlite_database_receiving(sql,owner));assert!(result.is_err());assert_eq!(born,freed);let(result,_,born,freed)=encode(policy,&mut |_|true,|sql,owner|JsonSnapshot::from_sqlite_database_receiving(&original,sql,owner));assert!(result.is_err());assert_eq!(born,freed);}for law in fixture("malformed").as_array().unwrap(){let mut original=input(0);if law["cycle"]==true{original.tables[1].rows.push(SqliteRow{rowid:99,values:vec![SqliteValue::Integer(99),SqliteValue::Text("array".into()),SqliteValue::Null,SqliteValue::Null,SqliteValue::Null,SqliteValue::Null]});original.tables[3].rows.push(SqliteRow{rowid:99,values:vec![SqliteValue::Integer(99),SqliteValue::Integer(99),SqliteValue::Integer(0),SqliteValue::Integer(99)]});}else{let table=original.tables.iter_mut().find(|table|table.name==law["table"].as_str().unwrap()).unwrap();let index=table.rows.iter().position(|row|row.rowid==law["rowid"].as_i64().unwrap()).unwrap();if law["remove"]==true{table.rows.remove(index);}else if law["duplicate"]==true{table.rows.push(table.rows[index].clone());}else{table.rows[index].values[law["column"].as_u64().unwrap()as usize]=scalar(&law["value"]);}}let pointer=original.tables.as_ptr();let(result,_,born,freed)=encode(paid,&mut |_|true,|sql,owner|JsonSnapshot::from_sqlite_database_receiving(&original,sql,owner));let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue,"{}",law["id"]);assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!(born,freed);assert_eq!(pointer,original.tables.as_ptr());}}

