#[test]
fn json_original_receiving_borrowed_named_diagnostics_preserve_actual_policy_and_original_backing(){let laws=fixture("grants");let paid=grant(&laws["body"]);let closing=grant(&laws["close"]);for index in 0..fixture("inputs").as_array().unwrap().len(){let original=input(index);let source=snapshot(index);for subset in ["*","i-json","geojson"]{let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.json".into(),standard:"rfc8259".into(),subset:subset.into()};let expected=source.validate_sqlite_snapshot_subset(&dialect,&original,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let pointer=source.schema.as_ptr();let(result,_,born,freed)=validate_decode(paid,&mut |_|true,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&dialect,&original,sql,owner).map_err(|error|error.cause));let result=result.unwrap();assert_eq!(result.diagnostics,expected.diagnostics);let(a,b)=close(result.diagnostics,closing);assert_eq!(born+a,freed+b);let(result,_,born,freed)=validate_encode(paid,&mut |_|true,|sql,owner|source.validate_sqlite_snapshot_subset_encoding(&dialect,&original,sql,owner).map_err(|error|error.cause));let result=result.unwrap();assert_eq!(result.diagnostics,expected.diagnostics);let(a,b)=close(result.diagnostics,closing);assert_eq!(born+a,freed+b);assert_eq!(pointer,source.schema.as_ptr());}}
 for(kind,standard,subset)in[("wrong","rfc8259","*"),("s.stdio.json","wrong","*"),("s.stdio.json","rfc8259","unknown")]{let original=input(0);let source=snapshot(0);let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:kind.into(),standard:standard.into(),subset:subset.into()};let(result,_,born,freed)=validate_decode(paid,&mut |_|true,|sql,owner|source.validate_sqlite_snapshot_subset_decoding(&dialect,&original,sql,owner).map_err(|error|error.cause));let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::UnsupportedOwner);assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!((born,freed),(0,0));}}
#[test]
fn json_original_receiving_original_zero_capacity_refuses_before_birth(){let laws=fixture("grants");let paid=grant(&laws["body"]);let source=snapshot(0);let original=input(0);
 macro_rules! direction{($native:ident,$owner:ident,$recipient:path,$call:expr)=>{{for(native_maximum,sql_maximum)in[(0,16777216),(16777216,0)]{let mut callback=|_|true;let mut recipient=<$recipient>::new();let mut native=$native::new(native_maximum,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();let mut sql=SqliteSnapshotControl::new(&mut |_|true,semio_framework_os_kernel::sqlite_snapshot::SqliteDatabaseLimits{max_allocation_bytes:sql_maximum,..Default::default()});let mut owner=$owner::new(&mut native,paid);let(result,heap)=observe(||($call)(&mut sql,&mut owner));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.progress(),RetainedCloneProgress::default());drop(owner);assert_eq!(native.owned_bytes(),0);assert!(!native.has_retirement_owner());}}};}
 direction!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotDecodeOwner<'_,'_>|source.to_sqlite_database_receiving(sql,owner));direction!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotEncodeOwner<'_,'_>|JsonSnapshot::from_sqlite_database_receiving(&original,sql,owner));}
#[test]
fn json_original_receiving_partial_utf8_and_lexeme_cancel_under_same_original_recipient(){use std::cell::Cell;let laws=fixture("grants");let paid=grant(&laws["body"]);let closing=grant(&laws["close"]);let denied=grant(&laws["denied"]);for (is_number,text) in [(false,"世界\0".repeat(32768)),(true,"1234567890".repeat(32768))]{let length=text.len();let source=JsonSnapshot{schema:"literal original".into(),value:if is_number{JsonValue::Number{lexeme:text.clone()}}else{JsonValue::String{value:text.clone()}}};let mut original=input(if is_number{3}else{4});original.tables[1].rows[0].values[if is_number{3}else{4}]=SqliteValue::Text(text);if is_number{original.tables[1].rows[0].values[5]=SqliteValue::Null;}
 macro_rules! direction{($native:ident,$owner:ident,$recipient:path,$call:expr)=>{{let blocked=Cell::new(false);let mut callback=|_|!blocked.get();let mut recipient=<$recipient>::new();let mut native=$native::new(16777216,&mut callback);native.install_retirement_recipient(&mut recipient).unwrap();let mut canceled=false;let mut sql_callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{let cut=event.total==length&&event.completed>=65536&&event.completed<length;canceled|=cut;!cut};let mut sql=SqliteSnapshotControl::new(&mut sql_callback,Default::default());let before=sql.allocation_remaining_bytes();let mut owner=$owner::new(&mut native,paid);let(result,heap)=observe(||($call)(&mut sql,&mut owner));let receipt=owner.progress();let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(error.message,"relational SQLite transfer cancelled");assert!(matches!(error.message,std::borrow::Cow::Borrowed(_)));assert_eq!(error.retained_progress(),receipt);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));drop(owner);assert_eq!(before-sql.allocation_remaining_bytes(),native.owned_bytes());drop(sql);assert!(canceled);assert!(native.has_retirement_owner());let(mut born,mut freed)=(heap.requested_bytes,heap.released_bytes);let(step,heap)=observe(||native.close_retirement_recipient(denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));blocked.set(true);let(result,heap)=observe(||native.close_retirement_recipient(closing));assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));blocked.set(false);for _ in 0..4096{if !native.has_retirement_owner(){break}let(step,heap)=observe(||native.close_retirement_recipient(closing).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(!native.has_retirement_owner());assert_eq!(born,freed);}};}
 direction!(NativeDecodeControl,NativeSnapshotDecodeOwner,semio_framework_value::native_decoding::NativeDecodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotDecodeOwner<'_,'_>|source.to_sqlite_database_receiving(sql,owner));direction!(NativeEncodeControl,NativeSnapshotEncodeOwner,semio_framework_value::native_encoding::NativeEncodeRetirementRecipient,|sql:&mut SqliteSnapshotControl<'_>,owner:&mut NativeSnapshotEncodeOwner<'_,'_>|JsonSnapshot::from_sqlite_database_receiving(&original,sql,owner));}}
#[semio_framework_async_macros::async_test]
async fn json_original_receiving_complete_typed_file_keeps_all_original_semantic_fields(){use semio_framework_os_kernel::{io::{testing::{SnapshotFileCaller,with_snapshot_file_decoding,with_snapshot_file_encoding},io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}},sqlite_snapshot::SnapshotEncoding};semio_framework_plugin::PluginBuilder::<_, semio_framework_plugin::app::NoPluginApp>::new("stdio").label("JSON original receiving file law").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let laws=fixture("grants");let policy=SnapshotFileCaller{grant:grant(&laws["body"]),native_maximum_bytes:16777216,close_grant:grant(&laws["close"]),maximum_close_turns:4096};let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.json".into(),standard:"rfc8259".into(),subset:"*".into()};let mut native_phase=false;for index in 0..fixture("inputs").as_array().unwrap().len(){let source=snapshot(index);let pointer=source.schema.as_ptr();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{native_phase|=matches!(event.phase,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative);true};let file=with_snapshot_file_decoding(policy,Default::default(),&mut callback,async|sql,owner|io_export_sqlite_snapshot(&dialect,&source,encoding,sql,owner).await).await.unwrap();assert!(file.diagnostics.is_empty());assert!(file.value.starts_with(b"SQLite format 3\0"));let restored=with_snapshot_file_encoding(policy,Default::default(),&mut callback,async|sql,owner|io_import_sqlite_snapshot::<JsonSnapshot>(&dialect,&file.value,sql,owner).await).await.unwrap();assert!(restored.diagnostics.is_empty());assert_eq!(restored.value,source);let _=close(restored.value,policy.close_grant);let _=close(file.value,policy.close_grant);}assert_eq!(pointer,source.schema.as_ptr());}assert!(!native_phase);}

fn runtime_fixture_text(relative: &str) -> &'static str {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(relative);
    Box::leak(std::fs::read_to_string(&path).unwrap_or_else(|error| panic!("fixture {}: {error}", path.display())).into_boxed_str())
}
